"""Independent R46 PDF checks; render review is still required."""
import argparse
from collections import Counter
import json
import math
from pathlib import Path
from pypdf import PdfReader

MM=72/25.4
NAMES=['林晨','周宁','陈晓','许舟','王瑜','李然']

def point(x,y,m):
    a,b,c,d,e,f=map(float,m)
    return a*x+c*y+e,b*x+d*y+f

assert point(1,2,[0,1,-1,0,10,20])==(8,21)

def check(path,fixed=False,updated=False):
    reader=PdfReader(path)
    errors=[];pages=[];counts=Counter()
    if len(reader.pages)!=(2 if fixed else 1):errors.append('Unexpected page count')
    for number,page in enumerate(reader.pages,1):
        width,height=float(page.mediabox.width)/MM,float(page.mediabox.height)/MM
        if abs(min(width,height)-210)>.3 or abs(max(width,height)-297)>.3:errors.append(f'Page{number}: not A4')
        if fixed and (width>height or page.rotation%360):errors.append(f'Page{number}: violates upright portrait paper')
        if float(page.get('/UserUnit',1))!=1:errors.append(f'Page{number}: unsupported UserUnit requires separate geometry review')
        boxes=[];angles=[]
        def operand(op,args,cm,tm):
            if op!=b're':return
            x,y,w,h=map(float,args)
            p=point(x,y,cm);u=point(x+w,y,cm);v=point(x,y+h,cm);z=point(x+w,y+h,cm)
            edges=[math.dist(p,u)/MM,math.dist(p,v)/MM]
            if not (abs(min(edges)-60)<.3 and abs(max(edges)-100)<.3):return
            box=[min(t[0] for t in [p,u,v,z])/MM,min(t[1] for t in [p,u,v,z])/MM,max(t[0] for t in [p,u,v,z])/MM,max(t[1] for t in [p,u,v,z])/MM]
            boxes.append(box)
            if fixed and (abs((u[0]-p[0])/MM-100)>.3 or abs(u[1]-p[1])>.3*MM or abs((v[1]-p[1])/MM-60)>.3):errors.append(f'Page{number}: rotated label')
        def text_visitor(text,cm,tm,font,size):
            if not any(name in text for name in NAMES):return
            angle=math.degrees(math.atan2(float(cm[1])*float(tm[0])+float(cm[3])*float(tm[1]),float(cm[0])*float(tm[0])+float(cm[2])*float(tm[1])))
            angles.append(angle)
            if fixed and abs(angle)>.1:errors.append(f'Page{number}: rotated name text')
        text=page.extract_text(visitor_operand_before=operand,visitor_text=text_visitor)
        for name in NAMES:counts[name]+=text.count(name)
        for i,box in enumerate(boxes):
            if box[0]<9.7 or box[1]<9.7 or box[2]>width-9.7 or box[3]>height-9.7:errors.append(f'Page{number}: margin violation')
            for other in boxes[:i]:
                xgap=max(box[0]-other[2],other[0]-box[2]);ygap=max(box[1]-other[3],other[1]-box[3])
                if max(xgap,ygap)<4.7:errors.append(f'Page{number}: overlap or insufficient gap')
        pages.append({'page':number,'widthMM':width,'heightMM':height,'rotation':page.rotation,'labelRectangles':boxes,'nameAngles':angles,'text':text})
    expected={name:1 for name in NAMES}
    if updated:expected.update({'林晨':2,'周宁':0})
    if dict(counts)!=expected:errors.append('Extracted name counts differ from requested copies; inspect rendering before interpreting extraction limitations')
    if sum(len(p['labelRectangles']) for p in pages)!=6:errors.append('Six correctly sized rectangle outlines not identified; geometry requires further inspection rather than assuming absent borders prove bad layout')
    return {'pdf':str(path),'fixed':fixed,'updated':updated,'errors':errors,'nameCounts':dict(counts),'expectedCounts':expected,'pages':pages,'limits':'Independent PDF operators/text checks. Rendered readability, page clipping, application reuse and actual physical printing are separate checks. Rectangles must correspond to real label borders on visual inspection.'}

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('pdf',type=Path);parser.add_argument('output',type=Path);parser.add_argument('--fixed',action='store_true');parser.add_argument('--updated',action='store_true');args=parser.parse_args()
    result=check(args.pdf,args.fixed,args.updated)
    args.output.write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'pages':len(result['pages']),'counts':result['nameCounts'],'errors':result['errors']},ensure_ascii=False))
